// This code has been fully generated by an AI.

package analysis

import (
	"math"
	"time"
)

// Time constants of the fitness model in days: fitness (chronic training
// load, CTL), fatigue (acute training load, ATL) and the chronic window of
// the acute:chronic workload ratio.
const (
	FitnessDays = 42
	FatigueDays = 7
	ChronicDays = 28
)

// FitnessDay is the state of the fitness model at the end of one day.
type FitnessDay struct {
	Date time.Time
	Load float64
	// Fitness (CTL) and Fatigue (ATL) are exponentially weighted averages
	// of the daily load; Form (TSB) is yesterday's fitness minus fatigue.
	Fitness float64
	Fatigue float64
	Form    float64
	// ACWR is the acute (7 d) to chronic (28 d) workload ratio, 0 while
	// the chronic load is still negligible.
	ACWR float64
}

// FitnessSeries runs the Banister model over daily loads (keyed by local
// date as UTC midnight) from the first loaded day up to and including to.
// Days without activities have load 0.
func FitnessSeries(loads map[time.Time]float64, to time.Time) []FitnessDay {
	if len(loads) == 0 {
		return nil
	}
	first := to
	for d := range loads {
		if d.Before(first) {
			first = d
		}
	}
	k := func(days float64) float64 { return 1 - math.Exp(-1/days) }
	kFit, kFat, kChr := k(FitnessDays), k(FatigueDays), k(ChronicDays)
	var fit, fat, chr float64
	var out []FitnessDay
	for d := first; !d.After(to); d = d.AddDate(0, 0, 1) {
		load := loads[d]
		form := fit - fat
		fit += (load - fit) * kFit
		fat += (load - fat) * kFat
		chr += (load - chr) * kChr
		day := FitnessDay{Date: d, Load: load, Fitness: fit, Fatigue: fat, Form: form}
		if chr > 1 {
			day.ACWR = fat / chr
		}
		out = append(out, day)
	}
	return out
}

// ACWRStatus classifies the workload ratio like common sports-science
// bands: below 0.8 detraining, up to 1.3 optimal, up to 1.5 high, above
// that a high injury risk.
func ACWRStatus(acwr float64) string {
	switch {
	case acwr == 0:
		return "–"
	case acwr < 0.8:
		return "niedrig"
	case acwr <= 1.3:
		return "optimal"
	case acwr <= 1.5:
		return "hoch"
	}
	return "sehr hoch"
}

// FormStatus describes the training stress balance.
func FormStatus(form float64) string {
	switch {
	case form > 5:
		return "erholt"
	case form >= -10:
		return "ausgeglichen"
	case form >= -30:
		return "produktive Belastung"
	}
	return "Überlastung"
}
